def validate_email(email: str) -> bool:
    """Return True if email is a basic valid email, False otherwise."""
    if ' ' in email:
        return False          # no spaces allowed

    if email.count('@') != 1:
        return False          # exactly one @

    local, domain = email.split('@')

    if not local:
        return False          # local part must be non-empty

    if not domain or '.' not in domain:
        return False          # domain must have a dot

    if domain.startswith('.') or domain.endswith('.'):
        return False          # domain can't start/end with dot

    if '..' in domain:
        return False          # no consecutive dots in domain

    return True               # all checks passed
```

