/**
 * Debounce function to delay callback execution.
 * @param {function} callback - The function to be executed after the delay.
 * @param {number} delay - The delay in milliseconds.
 * @returns {function} A new function that debounces the callback execution.
 */
function debounce(callback, delay) {
    let timeoutId;

    return function(...args) {
        // Reset the timer if the function is called again
        if (timeoutId) {
            globalThis.clearTimeout(timeoutId);
        }

        // Set a new timer to delay the callback execution
        timeoutId = globalThis.setTimeout(() => {
            callback(...args);
        }, delay);
    };
}

