```javascript
/**
 * Creates a debounced version of the provided callback.
 * The callback is only executed after `delay` milliseconds have passed
 * since the last time the returned function was invoked.
 * If called again before the delay, the timer resets.
 *
 * @param {Function} callback - The function to debounce.
 * @param {number} delay - The delay in milliseconds.
 * @returns {Function} The debounced function.
 *
 * @example
 * // Usage: limit search input to fire only after 300ms of inactivity
 * const search = debounce((query) => {
 *   console.log(`Searching for "${query}"...`);
 *   // perform API call here
 * }, 300);
 *
 * // Simulate rapid calls
 * search('a');
 * search('ap');
 * search('app');
 * search('appl');
 * search('apple'); // only this one triggers after 300ms pause
 */
function debounce(callback, delay) {
  let timerId;

  // Return a new function that captures the context and arguments
  return function (...args) {
    // Clear any previously set timer
    if (timerId) {
      clearTimeout(timerId);
    }

    // Schedule execution after the specified delay
    timerId = setTimeout(() => {
      callback.apply(this, args);
      timerId = null; // optional cleanup
    }, delay);
  };
}
```

