    }

    // Set a new timer.
    // The callback will only execute after 'delay' milliseconds,
    // *unless* this function is called again before that time.
    timeoutId = setTimeout(() => {
      // Execute the original callback with the correct 'this' context
      // and all the arguments that were passed to the debounced function.
      callback.apply(context, args);
    }, delay);
  };
