import csv
import sys

def calculate_stats(csv_file):
    """Calculates and prints summary statistics from a CSV file."""
    try:
        # Initialize variables to keep track of stats
        num_rows = 0
        num_cols = 0
        col_names = []
        numeric_cols = {}

        # Read the CSV file
        with open(csv_file, 'r') as file:
            reader = csv.reader(file)
            for row in reader:
                if num_rows == 0:
                    # Set the number of columns and column names on the first row
                    num_cols = len(row)
                    col_names = row

                    # Initialize numeric columns
                    for col in col_names:
                        numeric_cols[col] = {'min': float('inf'), 'max': float('-inf'), 'mean_sum': 0, 'count': 0}

                else:
                    # Iterate over each value in the row
                    for i, val in enumerate(row):
                        # Check if the value can be converted to a float (i.e., it's numeric)
                        try:
                            val_float = float(val)
                            numeric_cols[col_names[i]]['min'] = min(numeric_cols[col_names[i]]['min'], val_float)
                            numeric_cols[col_names[i]]['max'] = max(numeric_cols[col_names[i]]['max'], val_float)
                            numeric_cols[col_names[i]]['mean_sum'] += val_float
                            numeric_cols[col_names[i]]['count'] += 1
                        except ValueError:
                            pass

                num_rows += 1

        # Calculate means
        for col in numeric_cols:
            if numeric_cols[col]['count'] > 0:
                numeric_cols[col]['mean'] = numeric_cols[col]['mean_sum'] / numeric_cols[col]['count']
            else:
                numeric_cols[col]['mean'] = None

        # Print stats
        print(f"Number of rows: {num_rows - 1}")  # Subtract 1 for the header row
        print(f"Number of columns: {num_cols}")
        print(f"Column names: {col_names}")
        for col, stats in numeric_cols.items():
            if stats['count'] > 0:
                print(f"Column '{col}':")
                print(f"  Min: {stats['min']}")
                print(f"  Max: {stats['max']}")
                print(f"  Mean: {stats['mean']}")
            else:
                print(f"Column '{col}': Not numeric")

    except FileNotFoundError:
        print(f"File '{csv_file}' not found.")
    except Exception as e:
        print(f"An error occurred: {e}")

def main():
    if len(sys.argv) != 2:
        print("Usage: python script.py <csv_file>")
    else:
        csv_file = sys.argv[1]
        calculate_stats(csv_file)

if __name__ == "__main__":
    main()
